<?php if (!defined('ABSPATH')) exit; ?><article class="tranter-event-card" data-event-id="<?php echo esc_attr($e['id']); ?>"><button class="tranter-card-trigger" type="button" aria-label="View <?php echo esc_attr($e['title']); ?>"><div class="tranter-card-image"><?php if($e['image']): ?><img src="<?php echo esc_url($e['image']); ?>" alt="<?php echo esc_attr($e['title']); ?>" loading="lazy"><?php else: ?><div class="tranter-image-placeholder">TRANTER EVENTS</div><?php endif; ?><?php if($e['partner']): ?><span class="tranter-partner-badge"><?php echo esc_html($e['partner']['name']); ?></span><?php endif; ?></div><div class="tranter-card-body"><span class="tranter-card-meta"><?php echo esc_html($e['type']); ?> · <?php echo esc_html($e['date']); ?></span><h3><?php echo esc_html($e['title']); ?></h3><p><?php echo esc_html($e['short']); ?></p><span class="tranter-card-location"><?php echo esc_html($e['location']); ?></span><span class="tranter-card-link">View details →</span></div></button><?php if($e['registration_enabled']): ?><a class="tranter-register" href="<?php echo esc_url($e['registration_url']); ?>" target="_blank" rel="noopener"><?php echo esc_html($e['registration_text']); ?></a><?php endif; ?></article>
